import{_ as a,a as e}from"./chunks/dq-2.DyErWHxW.js";import{_ as r,o as l,c as o,a5 as i}from"./chunks/framework.DGp912Ge.js";const b=JSON.parse('{"title":"DQ 재보정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/dq-calibration.md","filePath":"ko/manual/troubleshooting/dq-calibration.md","lastUpdated":1785806767000}'),n={name:"ko/manual/troubleshooting/dq-calibration.md"};function s(d,t,g,h,c,p){return l(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="dq-재보정" tabindex="-1">DQ 재보정 <a class="header-anchor" href="#dq-재보정" aria-label="Permalink to &quot;DQ 재보정&quot;">​</a></h1><p>관절 보드 교체, 관절 모듈 교체 또는 인코더 영점이 틀어진 경우 <strong>DQ ALIGN</strong>으로 인코더 영점을 다시 설정합니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>DQ ALIGN 실행 시 해당 관절이 살짝 움직입니다. 로봇 주변에 사람이나 장애물이 없도록 하고, 로봇이 바닥에 안정적으로 놓인 상태에서 진행하세요.</p></div></div><h2 id="사전-준비" tabindex="-1">사전 준비 <a class="header-anchor" href="#사전-준비" aria-label="Permalink to &quot;사전 준비&quot;">​</a></h2><ul><li>RBQ GUI(PC 앱)가 로봇에 연결된 상태</li><li>로봇이 앉은 자세로 보정하려는 관절이 살짝 움직일 수 있는 상태</li></ul><hr><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;"></figcaption></figure><h2 id="절차" tabindex="-1">절차 <a class="header-anchor" href="#절차" aria-label="Permalink to &quot;절차&quot;">​</a></h2><h3 id="_1-leg-전원-켜기" tabindex="-1">1. LEG 전원 켜기 <a class="header-anchor" href="#_1-leg-전원-켜기" aria-label="Permalink to &quot;1. LEG 전원 켜기&quot;">​</a></h3><p>상단 탭에서 <strong>Power</strong>를 선택한 후 <strong>LEG 전원을 ON</strong>합니다.</p><h3 id="_2-조인트-테이블-열기" tabindex="-1">2. 조인트 테이블 열기 <a class="header-anchor" href="#_2-조인트-테이블-열기" aria-label="Permalink to &quot;2. 조인트 테이블 열기&quot;">​</a></h3><p>상단 메뉴 <strong>View → Show Bottom Bar</strong>를 클릭하면 화면 하단에 조인트 테이블이 열립니다.</p><h3 id="_3-조인트-탭으로-이동" tabindex="-1">3. 조인트 탭으로 이동 <a class="header-anchor" href="#_3-조인트-탭으로-이동" aria-label="Permalink to &quot;3. 조인트 탭으로 이동&quot;">​</a></h3><p>상단 탭에서 <strong>Joint</strong>를 선택합니다.</p><h3 id="_4-dq-align-실행" tabindex="-1">4. DQ ALIGN 실행 <a class="header-anchor" href="#_4-dq-align-실행" aria-label="Permalink to &quot;4. DQ ALIGN 실행&quot;">​</a></h3><ol><li><strong>Selected joint</strong>, <strong>Joint table</strong> 에서 보정할 관절을 선택합니다.</li><li><strong>DQ ALIGN</strong> 버튼을 누릅니다.</li><li>해당 관절이 <strong>살짝 움직이면서</strong> 인코더 영점을 잡습니다.</li><li><strong>BOARD RESET</strong> 버튼을 눌러 보드를 리셋합니다.</li></ol><h3 id="_5-나머지-관절-반복" tabindex="-1">5. 나머지 관절 반복 <a class="header-anchor" href="#_5-나머지-관절-반복" aria-label="Permalink to &quot;5. 나머지 관절 반복&quot;">​</a></h3><p>보정이 필요한 관절마다 <strong>4번 과정을 반복</strong>합니다.</p><hr><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;"></figcaption></figure><h2 id="보정-완료-확인" tabindex="-1">보정 완료 확인 <a class="header-anchor" href="#보정-완료-확인" aria-label="Permalink to &quot;보정 완료 확인&quot;">​</a></h2><p>하단 조인트 테이블의 <strong>Angle</strong> 값이 정상 범위로 표시되면 보정이 완료된 것입니다. 이후 <strong>Auto Start Robot</strong> 절차를 정상적으로 진행할 수 있습니다.</p><h2 id="언제-필요한가" tabindex="-1">언제 필요한가 <a class="header-anchor" href="#언제-필요한가" aria-label="Permalink to &quot;언제 필요한가&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">상황</th><th style="text-align:left;">DQ 재보정 필요 여부</th></tr></thead><tbody><tr><td style="text-align:left;">관절 보드 교체 후</td><td style="text-align:left;">필요</td></tr><tr><td style="text-align:left;">관절 모듈 전체 교체 후</td><td style="text-align:left;">필요</td></tr><tr><td style="text-align:left;">Find Home 실패가 반복될 때</td><td style="text-align:left;">필요할 수 있음</td></tr><tr><td style="text-align:left;">특정 관절이 초기화 후 이상한 각도를 가리킬 때</td><td style="text-align:left;">필요할 수 있음</td></tr><tr><td style="text-align:left;">정상 운영 중</td><td style="text-align:left;">불필요</td></tr></tbody></table>',24)])])}const f=r(n,[["render",s]]);export{b as __pageData,f as default};
